const toolsList=[['Proposal Builder','','Growth','Turn an RFP into a complete, evidence-backed proposal.'],['Lead Response','↗','Growth','Turn webinar engagement into thoughtful follow-up.'],['Lead Triage','⊞','Growth','Connect signals, prioritize leads, and route the next move.'],['Simulation Analysis','','Intelligence','Pressure-test your ideas with a simulated persona focus group.'],['Budget Builder','','Planning','Build departmental budgets through a conversation.'],['Sales Dashboard','','Intelligence','See where revenue has been—and where it is going.'],['Resource Allocation Platform','','Delivery','Balance people, priorities, and capacity with AI.'],['Collaboration Workspace','','Delivery','Bring teams, clients, contractors, and project work together.'],['Client Data Hub','','Intelligence','Bring client sales, delivery, and finance data together by account.'],['Forecast Builder','','Planning','Explore the assumptions behind your next quarter.'],['ROI Calculator','','Planning','Understand the value of a project before you build it.'],['Project Tracker','','Delivery','Track every AI initiative from discovery to impact.'],['Nightwatch','','Growth','Wake up to researched prospects and tailored outreach.']];
let current=-1,tab=0;const state={proposal:false,section:0,chat:[],response:false,approved:false,simulation:0,budget:[180000,85000,60000,45000],rebalance:false,role:'Internal team',posts:[],growth:12,win:32,adoption:75,hours:30,rate:65,build:24000,running:600,night:false,variant:0,channel:'Email',company:0,filter:'All',tasks:{},drafts:{},quarter:'Q4 2026'};
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>'$'+Math.round(n).toLocaleString();const btn=(s,fn,cls='')=>`<button class="${cls}" onclick="${esc(fn)}">${s}</button>`;const tag=(s,c='')=>`<span class="tag ${c}">${s}</span>`;const card=(title,body)=>`<section class="card"><h2>${title}</h2>${body}</section>`;const stats=arr=>`<div class="stats">${arr.map(([a,b,c])=>`<div class="stat"><label>${a}</label><strong>${b}</strong><small>${c}</small></div>`).join('')}</div>`;const tabs=arr=>`<div class="tabs">${arr.map((s,i)=>btn(s,`tab=${i};render()`,tab===i?'active':'')).join('')}</div>`;const bar=(n,green=false)=>`<div class="bar ${green?'green':''}"><i style="width:${Math.min(n,100)}%"></i></div>`;const field=(name,id,value,type='text')=>`<label class="field">${name}<input id="${id}" type="${type}" value="${esc(value)}"></label>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function nav(n){current=n;tab=0;location.hash=n<0?'overview':toolsList[n][0].toLowerCase().replaceAll(' ','-');render();window.scrollTo(0,0)}
function draw(title,body){$('#drawer').innerHTML=`<div class="row"><span class="eyebrow">Nine-67 / Explore</span>${btn('Close ×','closeDrawer()')}</div><h1>${title}</h1>${body}`;$('#overlay').hidden=false}
function closeDrawer(){$('#overlay').hidden=true}$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeDrawer()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
function title(desc,action=''){return `<div class="titlebar"><div><div class="eyebrow">${toolsList[current][2]} / AI workspace</div><h1>${toolsList[current][0]}</h1><p>${desc||toolsList[current][3]}</p></div>${action}</div>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function lineChart(mult=1){const vals=[85,74,90,68,75,46,55,32,39,20,26,10].map((v,i)=>`${40+i*43},${35+v*1.3/mult}`).join(' ');return `<svg class="chart" viewBox="0 0 560 220" role="img" aria-label="Monthly revenue trend with projected growth"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#b98c4f" stop-opacity=".22"/><stop offset="1" stop-color="#b98c4f" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map((y,i)=>`<line x1="35" y1="${y}" x2="540" y2="${y}" stroke="#eeeae2"/><text x="0" y="${y}" fill="#91897c" font-size="9">${4-i}M</text>`).join('')}<polygon points="40,190 ${vals} 513,190" fill="url(#area)"/><polyline points="40,162 83,150 126,160 169,138 212,140 255,120 298,130 341,102 384,106 427,88 470,90 513,72" fill="none" stroke="#ccc5ba" stroke-dasharray="5 5" stroke-width="2"/><polyline points="${vals}" fill="none" stroke="#a46b22" stroke-width="3"/>${['Jan','Mar','May','Jul','Sep','Nov'].map((x,i)=>`<text x="${40+i*86}" y="214" fill="#91897c" font-size="10">${x}</text>`).join('')}</svg>`}
function bars(labels,values){return `<div class="bars">${labels.map((l,i)=>`<div class="column" style="height:${values[i]}%" title="${l}: ${values[i]}" onclick="toast('${l}: ${values[i]} in this sample')"><b>${values[i]}</b><span>${l}</span></div>`).join('')}</div>`}
function render(){ $('#sidebar').innerHTML=`<div class="brand"><span class="moon"></span>Nine-67</div><div class="navlabel">PROJECT STUDIO</div>${btn('<span class="ico"></span> Overview', 'nav(-1)','nav '+(current<0?'active':''))}<div class="navlabel">EXPLORE THE TOOLS <small>13</small></div>${toolsList.map((x,i)=>btn(`<span class="ico">${x[1]}</span>${x[0]}`,`nav(${i})`,'nav '+(current===i?'active':''))).join('')}<div class="sidefoot"><b>Built around your business.</b><br>Your people. Your workflows.<br>Your next possibility.</div>`;$('#crumb').innerHTML=`Project Studio &nbsp; / &nbsp; <b style="color:var(--ink)">${current<0?'Overview':toolsList[current][0]}</b>`;$('#main').innerHTML=current<0?overview():[proposal,response,triage,simulation,budget,sales,resources,collaboration,insights,forecast,roi,tracker,nightwatch][current]();}
function overview(){return `<div class="titlebar"><div><div class="eyebrow">THE NINE-67 PROJECT STUDIO</div><h1>Real workflows. New possibilities.</h1><p>Explore what AI can do across your business.</p></div>${btn('Start the walkthrough →','nav(0)','primary')}</div><div class="hero"><div class="heroCopy"><div class="eyebrow">FROM THE FIRST SIGNAL TO THE NEXT DECISION</div><h1>A better way to work.<br>Built around you.</h1><p>Thirteen connected tools that turn everyday complexity into clear action. Step inside, change the inputs, and see the work move forward.</p>${btn('Explore the tools ↓',"document.getElementById('catalog').scrollIntoView({behavior:'smooth'})",'gold')}</div><div class="heroArt"><div class="flowrow">01 &nbsp; Find the opportunity <span>Nightwatch → Lead Triage</span></div><div class="flowrow">02 &nbsp; Build the response <span>Proposal → Simulation</span></div><div class="flowrow">03 &nbsp; Deliver the work <span>Workspace → Resources</span></div><div class="flowrow">04 &nbsp; Measure what matters <span>Insights → Forecast → ROI</span></div></div></div>${stats([['Purpose-built tools','13','Explore every workspace'],['Connected journeys','4','Growth · Delivery · Planning · Intelligence'],['One consistent experience','Nine-67','Built for your team'],['Your next step','Try it','Change an input. See the outcome.']])}<div class="sectionline" id="catalog"><h2>Your AI workspaces</h2><div class="suggestions">${['All','Growth','Delivery','Planning','Intelligence'].map(x=>btn(x,`state.filter='${x}';render()`,state.filter===x?'primary':'')).join('')}</div></div><div class="grid">${toolsList.map((x,i)=>state.filter==='All'||state.filter===x[2]?`<button class="toolcard" onclick="nav(${i})">${tag(x[2])}<h2>${x[1]} &nbsp;${x[0]}</h2><p>${x[3]}</p><span class="go">Open workspace &nbsp; ↗</span></button>`:'').join('')}</div>`}
const sections=['Executive summary','Approach & deliverables','Timeline & milestones','Investment','Requirements review'];
function proposal(){return title(null,btn('Use sample RFP',"state.proposal=true;state.chat.push(['ai','Sample RFP loaded: Operations Modernization. I found 12 requirements, a 90-day delivery window, and a $75,000 budget. What outcome matters most to the selection team?']);render()",'primary'))+tabs(['Conversation','Proposal editor','Requirements & review'])+(tab===0?`<div class="two equal">${card('Let’s build your next proposal.',`<p class="muted">Start with a conversation. Add the RFP when you’re ready.</p><div class="chat"><div class="bubble">Tell me what you’re responding to. I can help clarify the scope, map requirements, and build a proposal with you.</div>${state.chat.map(([role,s])=>`<div class="bubble ${role==='user'?'user':''}">${esc(s)}</div>`).join('')}</div><div class="suggestions">${btn('Build a 90-day pilot',"proposalChat('Build a 90-day pilot')")}${btn('What information do you need?',"proposalChat('What information do you need?')")}</div><label class="field">Attach an RFP <input type="file" accept=".pdf,.docx,.txt" onchange="proposalUpload(this)"></label><div class="composer"><input id="proposalInput" placeholder="Tell me about the opportunity…" onkeydown="if(event.key==='Enter')proposalChat()">${btn('Send ↑','proposalChat()','primary')}</div>`)}<div class="stack">${card('Proposal brief',`<div class="row">${tag(state.proposal?'RFP added':'Ready for your RFP',state.proposal?'green':'')}<span class="subtle">01 / 04</span></div><h1 style="font-size:24px">Operations Modernization</h1><p class="muted">An illustrative proposal for a 90-day AI pilot across operations and reporting.</p>${['Understand the requirements','Agree on the approach','Build the response','Review and refine'].map((s,i)=>`<div class="step"><span class="num">${state.proposal&&i===0?'✓':i+1}</span><div><b>${s}</b><p class="muted">${['Scope, success measures, and source materials','Confirm deliverables with your team','Draft sections from the conversation','Check coverage, evidence, and commitments'][i]}</p></div></div>`).join('')}${btn('Open proposal editor →','state.proposal=true;tab=1;render()','primary')}`)}<div class="callout"><b>From chat to a working document.</b><br>Your conversation shapes a proposal you can edit, review, and export. This demo uses a sample RFP; uploaded files are named locally and are not sent to AI.</div></div></div>`:tab===1?`<div class="two"><div class="card"><div class="row"><h2>Proposal sections</h2>${tag('Draft','amber')}</div><div class="suggestions">${sections.map((s,i)=>btn(s,`state.section=${i};render()`,state.section===i?'primary':'')).join('')}</div><label class="field">${sections[state.section]}<textarea id="proposalText" style="min-height:330px" oninput="state.drafts[state.section]=this.value">${esc(state.drafts[state.section]||proposalText())}</textarea></label><div class="row">${btn('Refine with AI',"refineProposal()")}${btn('Export proposal ↓','exportProposal()','primary')}</div></div>${card('Formatted preview',`<div class="document"><span class="eyebrow">NINE-67 / PROPOSAL</span><h2>${sections[state.section]}</h2><div id="previewText" style="white-space:pre-wrap;font-size:13px">${esc(state.drafts[state.section]||proposalText())}</div></div><p class="subtle">Editing is retained while you explore the demo.</p>`)}</div>`:card('Requirements & quality review',table(['Requirement','Source','Coverage','Action'],[['90-day pilot delivery','RFP §2',tag('Covered','green'),btn('View section','state.section=2;tab=1;render()')],['Budget within $75,000','RFP §4',tag('Covered','green'),btn('View investment','state.section=3;tab=1;render()')],['Named project owner','RFP §3',tag('Needs input','amber'),btn('Add owner',"draw('Assign a project owner',field('Owner name','owner','Alex Morgan')+btn('Save owner',\"state.drafts[1]=(state.drafts[1]||proposalText())+'\\nProject owner: '+document.getElementById('owner').value;closeDrawer();toast('Owner added to approach')\",'primary'))")],['Evidence of similar work','RFP §5',tag('Needs evidence','amber'),btn('Review with personas','nav(3)')]])+`<div class="callout">Review flags are illustrative. Confirm source evidence and commitments before using a real proposal.</div>`));}
function proposalText(){return ['We propose a 90-day operations modernization pilot that helps your team reduce manual reporting and improve visibility across projects.\n\nThe first working iteration will be delivered in two weeks. Together, we will validate the workflow, measure adoption, and refine the solution around your team’s feedback.\n\nSuccess measures: reporting time, data completeness, and weekly active usage.','Phase 1: Map the current workflow and confirm the data sources.\nPhase 2: Build a shared operations dashboard with AI-assisted summaries.\nPhase 3: Pilot with two departments, train owners, and refine based on feedback.\n\nDeliverables include a working application, documented integrations, and a handover plan.','Weeks 1–2: Discovery and first working iteration.\nWeeks 3–6: Integration and team feedback.\nWeeks 7–10: Broader pilot and refinements.\nWeeks 11–13: Measurement, handover, and next-phase plan.','Illustrative pilot investment: $60,000.\nDiscovery and workflow design: $10,000.\nBuild and integration: $35,000.\nPilot, training, and refinement: $15,000.\n\nCloud and model usage are estimated separately.','12 requirements identified.\n10 have a corresponding draft section.\n2 require owner confirmation or supporting evidence.'][state.section]}
function proposalChat(value){let v=value||$('#proposalInput').value;if(!v.trim())return;state.chat.push(['user',v]);state.proposal=true;state.chat.push(['ai',/information|need/i.test(v)?'Let’s start with three things: the RFP deadline, the team’s biggest workflow problem, and the evidence you can share. Who will approve the proposal?':`I’ll use “${v}” as a priority in the sample brief. A useful starting point is a two-week first iteration, followed by validation and refinement through day 90. Would you like the proposal to emphasize time savings, capacity, or decision quality?`]);render()}
function proposalUpload(el){if(el.files[0]){state.proposal=true;state.chat.push(['ai',`Attached: ${el.files[0].name}. This prototype does not parse uploaded documents. Use the sample RFP to explore the full proposal flow.`]);render()}}
function refineProposal(){state.drafts[state.section]=($('#proposalText').value)+'\n\nAcceptance criteria: the pilot owner will review a working demonstration every two weeks and sign off against agreed success measures.';render();toast('Sample refinement added')}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function exportProposal(){download('Nine-67-proposal.txt','Nine-67\nIllustrative proposal\n\n'+sections.map((s,i)=>{let old=state.section;state.section=i;let t=state.drafts[i]||proposalText();state.section=old;return s+'\n'+t}).join('\n\n'));}
