function budgetDetail(i){draw(['Operations','Marketing','Technology','People'][i],`<p>Annual allocation: <b>${money(state.budget[i])}</b></p>${table(['Category','Allocation'],[['People',money(state.budget[i]*.65)],['Tools & infrastructure',money(state.budget[i]*.25)],['Contingency',money(state.budget[i]*.1)]])}${btn('Return to plan','closeDrawer()','primary')}`)}function budgetAsk(){let v=$('#budgetAsk').value;let m=v.match(/(reduce|add|increase).*?(\d+)/i);if(m){let i=/tech/i.test(v)?2:/market/i.test(v)?1:/people/i.test(v)?3:0;state.budget[i]=Math.round(state.budget[i]*(1+(m[1].toLowerCase()==='reduce'?-1:1)*+m[2]/100));render();toast('Sample budget updated')}else $('#budgetReply').innerHTML='<p class="bubble">The plan is '+money(state.budget.reduce((a,b)=>a+b,0))+'. Operations drives most of the variance. In this demo, ask to increase or reduce a department by a percentage.</p>'}
