function forecast(){let projected=3.84*(1+state.growth/100)*(state.win/32);return title(null,btn('Save scenario',"toast('Scenario retained for this session')",'primary'))+tabs(['Scenario workspace','Assumptions','Compare scenarios'])+stats([['Baseline revenue','$3.84M','Current quarter'],['Scenario revenue','$'+projected.toFixed(2)+'M','Calculated from your assumptions'],['Change vs baseline',((projected/3.84-1)*100).toFixed(1)+'%','Sensitivity estimate'],['Planning horizon','90 days','Next quarter']])+`<div class="two">${card(tab===2?'Compare the possibilities':'Revenue outlook',`${lineChart(projected/3.84)}${table(['Scenario','Revenue','Assumptions'],[['Conservative','$3.80M','5% growth · 30% win rate'],['Baseline','$3.84M','Current-quarter reference'],['Your scenario','$'+projected.toFixed(2)+'M',state.growth+'% growth · '+state.win+'% win rate']])}`)}${card('Change the assumptions',`<label class="field">Pipeline growth <b style="float:right">${state.growth}%</b><input type="range" min="-10" max="40" value="${state.growth}" oninput="state.growth=+this.value;render()"></label><label class="field">Win rate <b style="float:right">${state.win}%</b><input type="range" min="15" max="50" value="${state.win}" oninput="state.win=+this.value;render()"></label><div class="callout"><b>What changed?</b><br>Your scenario is ${money(Math.abs(projected-3.84)*1000000)} ${projected>=3.84?'above':'below'} baseline. Both pipeline growth and conversion affect this estimate.</div><p class="subtle">Formula: baseline × (1 + pipeline growth) × (scenario win rate ÷ baseline win rate). Illustrative sensitivity model, not a prediction.</p><div class="suggestions">${btn('Conservative','state.growth=5;state.win=30;render()')}${btn('Growth','state.growth=20;state.win=38;render()')}${btn('Reset','state.growth=12;state.win=32;render()')}</div>`)}</div>`;}
function roi(){let gross=state.hours*52*state.rate*state.adoption/100,net=gross-state.running*12,year=net-state.build,roiPct=year/state.build*100;return title('Make the business case before you make the investment.',btn('Export analysis ↓',`download('Nine-67-ROI-analysis.txt','Nine-67 — illustrative ROI analysis\\nAnnual gross benefit: ${money(gross)}\\nAnnual net recurring benefit: ${money(net)}\\nBuild cost: ${money(state.build)}\\nFirst-year net: ${money(year)}\\nROI: ${roiPct.toFixed(1)}%')`))+tabs(['Business case','Assumptions & evidence','Sensitivity'])+stats([['Annual gross benefit',money(gross),'Time savings × adoption'],['Year-one net value',money(year),'After build and running costs'],['Year-one ROI',roiPct.toFixed(0)+'%','Net value ÷ build cost'],['Payback',net>0?(state.build/net*12).toFixed(1)+' months':'No payback','Based on net recurring benefit']])+`<div class="two equal">${card('Model your project',`<label class="field">Hours saved per week <b style="float:right">${state.hours}</b><input type="range" min="5" max="120" value="${state.hours}" oninput="state.hours=+this.value;render()"></label><label class="field">Expected adoption <b style="float:right">${state.adoption}%</b><input type="range" min="10" max="100" value="${state.adoption}" oninput="state.adoption=+this.value;render()"></label><div class="two equal"><label class="field">Loaded hourly cost<input type="number" min="1" value="${state.rate}" onchange="state.rate=Math.max(1,+this.value);render()"></label><label class="field">One-time build cost<input type="number" min="1" value="${state.build}" onchange="state.build=Math.max(1,+this.value);render()"></label></div><label class="field">Monthly running cost<input type="number" min="0" value="${state.running}" onchange="state.running=Math.max(0,+this.value);render()"></label>`)}${card(tab===2?'Adoption sensitivity':'The investment picture',`${table(['Value driver','Annual estimate'],[['Hours saved at full adoption',(state.hours*52).toLocaleString()+' hrs'],['Realized time benefit',money(gross)],['Cloud, model & maintenance','−'+money(state.running*12)],['Net recurring benefit',money(net)],['Year-one net after build',money(year)]])}<div class="callout" style="margin-top:22px"><b>${year>0?'Positive first-year case':'Review the investment assumptions'}</b><br>${year>0?'The sample benefits exceed build and running costs under these assumptions.':'The sample does not recover its costs in the first year. Adjust scope or validate additional benefits.'} Time savings represent capacity value, not guaranteed cash savings.</div><p class="subtle">Evidence grade: C · All inputs are estimates. Validate baseline time and adoption with the workflow owner.</p>${tab===2?table(['Adoption','Year-one net'],[25,50,75,100].map(a=>[a+'%',money(state.hours*52*state.rate*a/100-state.running*12-state.build)])):''}`)}</div>`;}
