function projectDetail(i){draw(projects[i],`${tag([1,4].includes(i)?'Needs attention':'On track',[1,4].includes(i)?'amber':'green')}<p>Project owner: Alex Morgan · Delivery partner: Nine-67</p><h2>Milestone plan</h2>${['Confirm workflow and success measures','Connect approved data sources','Demonstrate the first iteration','Pilot, measure, and refine'].map((s,j)=>`<div class="step"><span class="num">${j<2?'✓':j+1}</span><span>${s}</span></div>`).join('')}<h2 style="margin-top:24px">Project update</h2><textarea id="projectnote" placeholder="Add a decision or update…"></textarea>${btn('Save project update',"closeDrawer();toast('Project update saved in this demo')",'primary')}<div class="suggestions">${btn('Open collaboration workspace','closeDrawer();nav(7)')}${btn('Review business case','closeDrawer();nav(10)')}</div>`)}
const companies=['Northstar Manufacturing','Cedar Ridge Services','Harbor Supply','Summit Works'];const versions=['Concrete idea','Direct offer','Delivery experience'];
function nightwatch(){let company=companies[state.company];return title('Your next conversation starts before your day does.',btn(state.night?'Research complete ✓':'Run sample research ','state.night=true;render();toast("Sample research complete: 4 prospects ready")','primary'))+tabs(['Morning briefing','Companies & drafts','Research settings'])+stats([['Researched overnight',state.night?'54':'50','Sample research run'],['Qualified companies',state.night?'28':'24','Matched to target profile'],['Outreach drafts','72','3 versions per prospect'],['Ready for review','12','Email & LinkedIn']])+(tab===0?`<div class="two">${card('Today’s opportunities',table(['Company','Signal','Fit',''],companies.map((c,i)=>[`<b>${c}</b><small>${['Manufacturing · Pennsylvania','Services · New Jersey','Distribution · New York','Engineering · Pennsylvania'][i]}</small>`,['New facility expansion','Hiring operations leaders','ERP modernization','Growing project backlog'][i],tag([94,89,86,82][i],'green'),btn('Explore →',`state.company=${i};tab=1;render()`)])))}${card('While you were away',`<div class="activity">01 · Research target companies<small>Industry, size, geography, and relevant signals</small></div><div class="activity">02 · Find the right conversation<small>Business issue, decision-maker, and useful starting point</small></div><div class="activity">03 · Draft three approaches<small>Concrete idea · Direct offer · Delivery experience</small></div><div class="callout" style="margin-top:20px"><b>Human judgment stays in the loop.</b><br>Review research, choose the angle, and tailor the message.</div>`)}</div>`:tab===1?`<div class="two"><div class="stack">${card('Company intelligence',`<select onchange="state.company=+this.value;render()">${companies.map((x,i)=>`<option value="${i}" ${state.company===i?'selected':''}>${x}</option>`).join('')}</select><h1 style="font-size:25px">${company}</h1>${tag('Strong workflow fit','green')}<p class="muted">Illustrative established business with work distributed across people, locations, and systems.</p><div class="callout"><b>Why now</b><br>${['A new facility increases the need for consistent reporting across locations.','Leadership hiring suggests a focus on scalable operations.','A systems transition creates an opportunity to simplify handoffs.','A growing backlog makes capacity visibility more valuable.'][state.company]}</div><div class="listitem"><b>The idea to explore</b><p>A shared view of operational exceptions, ownership, and next actions.</p></div>${btn('View research brief',"draw('Research brief','<div class=callout>Illustrative company research for demonstration. No claims here are verified facts about a real business.</div><h2 style=margin-top:24px>Research checklist</h2><p>Company size and geography<br>Operational signal and source date<br>Relevant decision-maker<br>Contact confidence and suppression check</p>')",'link')}`)}</div>${card('Outreach studio',`<div class="suggestions">${['Email','LinkedIn'].map(x=>btn(x,`state.channel='${x}';render()`,state.channel===x?'primary':'')).join('')}</div><div class="three">${versions.map((x,i)=>btn(x,`state.variant=${i};render()`,state.variant===i?'gold':'')).join('')}</div><p class="subtle">Three approaches. One relevant conversation.</p>${field('Subject','outSubject','One workflow idea for '+company)}<label class="field">${state.channel} draft<textarea id="outreach" style="min-height:240px">${esc(outreachText())}</textarea></label><div class="row">${btn('Save edits',"state.drafts['out'+state.company+state.channel+state.variant]=document.getElementById('outreach').value;toast('Draft saved for this session')")}${btn('Mark ready',"toast('Sample draft marked ready. No outreach was sent.')",'primary')}</div>`)}</div>`:card('Your nightly research brief',`<div class="two equal"><div>${field('Target industries','industries','Manufacturing, professional services, distribution')}${field('Geography','geography','Pennsylvania, New York, New Jersey')}${field('Revenue range','revenue','$10M–$1B')}</div><div>${field('Research time','time','02:00','time')}${field('Companies per run','count',50,'number')}<label class="field">Research focus<select><option>Operational friction & growth signals</option><option>New leadership & expansion</option><option>Technology & systems changes</option></select></label></div></div><div class="callout">Demo configuration only. A production workflow can include contact verification, suppression lists, research provenance, and review gates.</div>${btn('Save research brief',"toast('Sample research settings saved; no scheduled job created')",'primary')}`));}
function outreachText(){let saved=state.drafts['out'+state.company+state.channel+state.variant];if(saved)return saved;let c=companies[state.company];return (state.channel==='Email'?'Hi there,\n\n':'')+[ `One idea for ${c}: bring branch reports, exceptions, and ownership into one shared view so your team can act without chasing updates. Would it be useful to compare that with your current workflow?`,`Could we spend 20 minutes looking at one recurring workflow at ${c}? We can help identify a practical first AI project and the measures that would make it worthwhile.`,`Our approach starts with a working first iteration, then improves through team feedback. For ${c}, a reporting and handoff pilot could be a useful place to explore. Open to a conversation?`][state.variant]+(state.channel==='Email'?'\n\nBest,\nThe Nine-67 team':'')}
function openArchitecture(){draw('Connected to the way you work.',`<p class="muted">A flexible technology foundation for Nine-67 projects. Integrations are illustrative in this prototype.</p>${[['Microsoft Teams','Conversations, notifications, and team collaboration'],['SharePoint','Project files, document libraries, and shared knowledge'],['Vercel','Application delivery and web hosting'],['Supabase','Application data, storage, and authentication'],['Azure','Cloud infrastructure and enterprise services'],['Claude API','Language understanding, drafting, and workflow assistance'],['OpenAI API','Reasoning, generation, and AI-enabled experiences']].map(([n,d])=>`<div class="listitem"><b>${n}</b><p>${d}</p>${tag('Available architecture option')}</div>`).join('')}<div class="callout" style="margin-top:20px">The deployment and integration design is tailored to each client’s requirements. This demo makes no external API calls.</div>`)}
document.addEventListener('input',e=>{if(e.target.id==='proposalText'&&$('#previewText'))$('#previewText').innerHTML=typeof proposalMarkup==='function'?proposalMarkup(e.target.value):esc(e.target.value)});let initial=location.hash.slice(1).split('/')[0];current=toolsList.findIndex(x=>x[0].toLowerCase().replaceAll(' ','-')===initial);
